using EqlTracker.Core;
using System.Text.Json;
internal static class ClearItemTests
{
    internal static void Register(Action<string, Action> test)
    {
        void Check(bool value) { if (!value) throw new Exception("Clear item evidence assertion failed"); }
        ItemDefinition Blade() => new() { Key = "blade", Name = "Blade", Slots = ["PRIMARY"], Classes = ["WAR"], MetadataComplete = true, Effects = ["Siphon Strength (Must Equip, Casting Time: 6.0) at Level 5", "Effect: Siphon Strength (Must Equip, Casting Time: 6.0) at Level 5"] };
        LoadoutProfile Owner() => new() { Classes = ["WAR"], EquipmentPositions = EquipmentPositions.FromEntries([new() { Name = "Old blade +2", Location = "Primary", Count = 1 }]) };
        test("Current inventory update defaults on and badge defaults to chest", () => { var p = JsonSerializer.Deserialize<CharacterProfile>("{}")!; Check(p.UpdateCurrentBuildFromInventory && p.InventoryBadge == InventoryBadgeStyle.Chest); });
        test("Current update and mimic preferences survive restart", () => { var p = new CharacterProfile { UpdateCurrentBuildFromInventory = false, InventoryBadge = InventoryBadgeStyle.FrierenMimic }; var copy = JsonSerializer.Deserialize<CharacterProfile>(JsonSerializer.Serialize(p))!; Check(!copy.UpdateCurrentBuildFromInventory && copy.InventoryBadge == InventoryBadgeStyle.FrierenMimic); });
        test("Legacy single draft migrates additively exactly once", () => { var o = Owner(); o.EquipmentDraft = new() { Positions = EquipmentPositions.Copy(o.EquipmentPositions), Undo = [EquipmentPositions.Copy(o.EquipmentPositions)] }; string old = JsonSerializer.Serialize(o.EquipmentDraft); GearBuildEditing.Migrate(o); GearBuildEditing.Migrate(o); Check(o.GearBuilds.Count == 1 && o.GearBuilds[0].Undo.Count == 1 && old == JsonSerializer.Serialize(o.EquipmentDraft)); });
        test("New from Current copies exact entries without ownership changes", () => { var o = Owner(); var b = GearBuildEditing.Create(o, "Copy"); b.Positions[0].Item!.Name = "Edited +10"; Check(o.EquipmentPositions[0].Item!.Name == "Old blade +2" && b.Id.Length > 0); });
        test("New empty build records empty rather than unknown", () => { var b = GearBuildEditing.Create(Owner(), "Empty", true); Check(b.Positions.Count > 19 && b.Positions.All(p => p.Knowledge == EquipmentKnowledge.Empty && p.Item == null)); });
        test("Current edits and Undo preserve ranks and effects", () => { var o = Owner(); string before = EquipmentPositions.Fingerprint(o.EquipmentPositions); GearBuildEditing.Remember(o, null); var positions = EquipmentPositions.Copy(o.EquipmentPositions); positions[0].Item!.Name = "Blade +10"; positions[0].Item!.Augments = [new() { Name = "Proc (Exaltation)", EffectText = "Proc: Earthquake" }]; GearBuildEditing.SetPositions(o, null, positions); Check(o.Equipment[0].Rank == 10 && GearBuildEditing.Undo(o, null) && before == EquipmentPositions.Fingerprint(o.EquipmentPositions)); });
        test("Use as Current needs no confirmation and remains undoable", () => { var o = Owner(); string before = EquipmentPositions.Fingerprint(o.EquipmentPositions); var b = GearBuildEditing.Create(o, "Empty", true); Check(GearBuildEditing.UseCurrent(o, b, out _) && o.Equipment.Count == 0 && GearBuildEditing.Undo(o, null) && before == EquipmentPositions.Fingerprint(o.EquipmentPositions)); });
        test("Named-build Undo restores name and theory assumptions", () => { var o = Owner(); var b = GearBuildEditing.Create(o, "Original"); b.Assumptions = ["Original assumption"]; GearBuildEditing.Remember(o, b); b.Name = "Renamed"; b.Assumptions = ["Changed"]; Check(GearBuildEditing.Undo(o, b) && b.Name == "Original" && b.Assumptions.Single() == "Original assumption"); });
        test("Theorycraft activation blocked in underlying command", () => { var o = Owner(); var b = GearBuildEditing.Create(o, "Theory"); b.IsTheorycraft = true; string before = JsonSerializer.Serialize(o.EquipmentPositions); Check(!GearBuildEditing.UseCurrent(o, b, out _) && before == JsonSerializer.Serialize(o.EquipmentPositions)); });
        test("Unsaved Gear theory edits cannot leak through profile saves", () => { var o = Owner(); var source = GearBuildEditing.Create(o, "Saved"); var w = new GearTheorycraftWorkspace(source); w.Working.Positions[0].Item!.Name = "Impossible"; Check(w.Dirty && !JsonSerializer.Serialize(o).Contains("Impossible") && o.GearBuilds.Count == 1); var saved = w.Save("Saved theory"); Check(saved.IsTheorycraft && !w.Dirty && saved.Id == w.SavedId); });
        test("Theorycraft reopen uses independent explicit-save working copy", () => { var b = new GearDraft { Name = "Theory", IsTheorycraft = true, Positions = Owner().EquipmentPositions }; var w = new GearTheorycraftWorkspace(b, true); Check(!w.Dirty); w.Working.Name = "Changed"; Check(w.Dirty && b.Name == "Theory"); });
        test("Export refreshes Current and preserves named builds", () => { var p = new CharacterProfile { Loadouts = [Owner()] }; var b = GearBuildEditing.Create(p.ActiveLoadout, "Saved"); string saved = JsonSerializer.Serialize(b); var inventory = new InventorySnapshot { Complete = true, EquipmentPositions = EquipmentPositions.FromEntries([new() { Name = "New blade +8", Location = "Primary", Count = 1 }]) }; Check(GearBuildEditing.ApplyExport(p, inventory) && p.ActiveLoadout.Equipment[0].Rank == 8 && JsonSerializer.Serialize(b) == saved); Check(GearBuildEditing.Undo(p.ActiveLoadout, null) && p.ActiveLoadout.Equipment[0].Rank == 2); });
        test("Disabled/incomplete export preserves Current", () => { var p = new CharacterProfile { UpdateCurrentBuildFromInventory = false, Loadouts = [Owner()] }; string before = EquipmentPositions.Fingerprint(p.ActiveLoadout.EquipmentPositions); var i = new InventorySnapshot { Complete = true }; Check(!GearBuildEditing.ApplyExport(p, i)); p.UpdateCurrentBuildFromInventory = true; i.Complete = false; Check(!GearBuildEditing.ApplyExport(p, i) && before == EquipmentPositions.Fingerprint(p.ActiveLoadout.EquipmentPositions)); });
        test("Siphon Strength is Click plus two with deduplicated source text", () => { var i = Blade(); ItemEffects.Normalize(i); var e = ExaltationPlanner.Build(new() { Items = [i] }, new()).Single(); Check(i.Effects.Count == 1 && e.Type == "Click" && e.UnlockRank == 2 && e.MatchesId("blade:unknown:siphon strength")); });
        test("Structured socket kinds override text fallback", () => Check(ItemEffects.Kind("Focus effect: Combat Fury") == "Focus" && ItemEffects.Kind("Proc: Flash (Casting Time: Instant)") == "Proc" && ItemEffects.Kind("Worn: Enduring Breath (Casting Time: Instant)") == "Worn"));
        test("Distinct explicit socket types sharing a spell remain separate", () => { var item = new ItemDefinition { Key = "x", Effects = ["Focus: Shared", "Proc: Shared"] }; ItemEffects.Normalize(item); Check(item.Effects.Count == 2 && ExaltationPlanner.Build(new() { Items = [item] }, new()).Count == 2); });
        test("Current effect IDs never alias another socket type", () => { var item = new ItemDefinition { Key = "x", Effects = ["Focus: Shared", "Proc: Shared"] }; var options = ExaltationPlanner.Build(new() { Items = [item] }, new()); Check(!options.Single(e => e.Type == "Proc").MatchesId(options.Single(e => e.Type == "Focus").Id)); });
        test("Proc assignment preserves Focus with the same spell name", () => { var source = new ItemDefinition { Key = "x", Name = "X", Slots = ["PRIMARY"], Classes = ["WAR"], MetadataComplete = true, Effects = ["Focus: Shared", "Proc: Shared"] }; var c = new Catalog { Items = [source] }; var effects = ExaltationPlanner.Build(c, new()); var focus = effects.Single(e => e.Type == "Focus"); var proc = effects.Single(e => e.Type == "Proc"); var entry = new PetInventoryItem { Slot = "Primary", Rank = 4, Exaltations = [new() { EffectId = focus.Id, Effect = focus.Effect }] }; Check(ExaltationPlanner.Assign(entry, proc, source, 4, "Primary", new() { Classes = ["MAG"], PetType = "Earth" }, c, "Planned", false, out _) && entry.Exaltations.Count == 2 && entry.Exaltations.Any(a => a.EffectId == focus.Id)); });
        test("Typed stored effect claims only its own socket type", () => { var source = new ItemDefinition { Key = "x", Name = "X", Effects = ["Focus: Shared", "Proc: Shared"] }; var effects = ExaltationPlanner.Build(new() { Items = [source] }, new() { Entries = [new() { Name = "Shared (Exaltation)", EffectText = "Focus: Shared", Location = "Augmentation", Count = null }] }); Check(effects.Single(e => e.Type == "Focus").Owned && !effects.Single(e => e.Type == "Proc").Owned); });
        test("Untyped same-name effect remains unresolved rather than double owned", () => { var source = new ItemDefinition { Key = "x", Name = "X", Effects = ["Focus: Shared", "Proc: Shared"] }; var effects = ExaltationPlanner.Build(new() { Items = [source] }, new() { Entries = [new() { Name = "Shared (Exaltation)", Location = "Augmentation", Count = null }] }); Check(effects.Where(e => e.Type is "Focus" or "Proc").All(e => !e.Owned) && effects.Single(e => e.Type == "Unknown").Owned); });
        test("Transferred-out effects survive prefix normalization", () => { var i = Blade(); ItemEffects.Normalize(i); Check(!ItemEffects.Active(i, ["Effect: Siphon Strength (Must Equip, Casting Time: 6.0) at Level 5"]).Any()); });
        test("Mount Utility purpose retains Click socket and future override", () => { var i = new ItemDefinition { Key = "black silken bridle", Name = "Black Silken Bridle", Effects = ["Summon Horse (Casting Time: 3.0)"] }; ItemEffects.Normalize(i); Check(i.ContentAvailability == ContentAvailability.Future && i.EffectEvidence.Single().SocketType == "Click" && i.EffectEvidence.Single().Purpose == EffectPurpose.Utility && i.AvailabilityEvidence.Contains("Wiki")); });
        test("Owned source is not an owned extracted effect", () => { var i = Blade(); ItemEffects.Normalize(i); var e = ExaltationPlanner.Build(new() { Items = [i] }, new() { Entries = [new() { Name = "Blade +1", Count = 1, Location = "Bank1" }] }).Single(); Check(!e.Owned && e.SourceOwned && !e.OwnershipEvidence.SourceReady); });
        test("Stored, socketed and keyring effect evidence stay distinguishable", () => { var i = Blade(); ItemEffects.Normalize(i); var stock = new InventorySnapshot { Entries = [new() { Name = "Blade (Exaltation)", Location = "Augmentation", Count = null }, new() { Name = "Blade (Exaltation)", Location = "General1", Count = 1 }, new() { Name = "Blade (Exaltation)", Location = "Primary-Slot1", Count = 1 }] }; var e = ExaltationPlanner.Build(new() { Items = [i] }, stock).Single(); Check(e.Owned && e.OwnershipEvidence.Stored && e.OwnershipEvidence.Socketed && e.OwnershipEvidence.Keyring); });
        test("Ownership badge collection evidence does not invent count", () => { var i = Blade(); var e = ItemOwnership.For(i, new() { CapturedAt = DateTime.Now, Entries = [new() { Name = "Blade", Count = null, Location = "Equipment" }] }); Check(e.Known && !e.QuantityKnown && e.Quantity == null); });
        test("Planned and pet gear cannot invent player ownership", () => Check(!ItemOwnership.For(Blade(), new()).Known));
        test("Slot priority and armor alphabetization are shared", () => Check(ItemPresentation.Slots(["RANGE", "SECONDARY", "PRIMARY"]) == "Primary / Secondary / Ranged" && ItemPresentation.Slots(["WRIST", "CHEST", "ARMS"]) == "Arms / Chest / Wrist"));
        test("Greatsword has distinct role; names do not infer type", () => { var i = Blade(); i.Display.Type = "2H Slashing"; Check(ItemPresentation.TypeRole(i) == "item-greatsword" && ItemPresentation.TypeRole(new() { Name = "Great Sword" }) == "glyph-unknown"); });
        test("Expansion inference uses source zones with caveat", () => { var i = new ItemDefinition { Sources = [new() { Zone = "Chardok" }] }; ItemExpansionEvidence.Apply(i, [new() { Zone = "Chardok", Expansion = "Kunark", Source = "Verified zones" }]); Check(i.IntroducedExpansion == "Unknown" && ItemPresentation.Expansion(i) == "Kunark" && ItemPresentation.ExpansionNote(i).Contains("Chardok")); });
        test("Confirmed introduction outranks provisional zone era", () => { var i = new ItemDefinition { IntroducedExpansion = "Velious", Sources = [new() { Zone = "Qeynos" }] }; ItemExpansionEvidence.Apply(i, [new() { Zone = "Qeynos", Expansion = "Classic" }]); Check(ItemPresentation.Expansion(i) == "Velious" && ItemPresentation.ExpansionNote(i) == ""); });
        test("Unknown zones remain unknown and conflicting map is not guessed", () => { var i = new ItemDefinition { Sources = [new() { Zone = "New Zone" }] }; ItemExpansionEvidence.Apply(i, [new() { Zone = "New Zone", Expansion = "Classic" }, new() { Zone = "New Zone", Expansion = "Kunark" }]); Check(ItemPresentation.Expansion(i) == "Unknown"); });
        test("Earliest supported acquisition zone wins without overriding introduction", () => { var i = new ItemDefinition { Sources = [new() { Zone = "Chardok" }, new() { Zone = "Qeynos" }] }; ItemExpansionEvidence.Apply(i, [new() { Zone = "Qeynos", Expansion = "Classic" }, new() { Zone = "Chardok", Expansion = "Kunark" }]); Check(ItemPresentation.Expansion(i) == "Classic" && i.IntroducedExpansion == "Unknown"); });
        test("Craft recipe parser requires sourced tradeskill rather than quest container", () => { var i = WikiClient.ParseItem("Banded Mail", "{{Itempage\n|itemname = Banded Mail\n|statsblock = Slot: CHEST<br>Class: ALL<br>Race: ALL<br>\n|playercrafted = \n* [[Blacksmithing]] (Trivial: 115)\n** In [[Forge]]:\n:: 1 x [[Mail Sectional Mold]] - Bought\n:: 3 x [[Sheet Metal]] - Crafted\n}}", 3); Check(i.CraftRecipes.Single().Kind == RecipeKind.Tradeskill && i.CraftRecipes.Single().Inputs.Sum(n => n.Count) == 4); var q = WikiClient.ParseItem("Quest", "{{Itempage\n|itemname = Quest\n|playercrafted = Combine [[Foo]] in [[Quest Box]].\n}}", 3); Check(q.CraftRecipes.Count == 0); });
        test("Have Drops and Ingredients keep partial stock and separate outputs", () => { var c = new Catalog { Items = [new() { Key = "drop", Name = "Drop" }, new() { Key = "ingredient", Name = "Ingredient" }, new() { Key = "crafted", Name = "Crafted", CraftRecipes = [new() { Kind = RecipeKind.Tradeskill, Inputs = [new() { ItemKey = "ingredient", Count = 3 }] }] }], Quests = [new() { Id = "q", RewardKey = "quest reward", Requirements = [new() { ItemKey = "drop", Count = 2 }] }] }; var inventory = new InventorySnapshot { Entries = [new() { Name = "Drop", Count = 1 }, new() { Name = "Ingredient", Count = 1 }] }; var m = new MaterialIndex(c, inventory, new()); Check(m.For("quest reward", RecipeKind.Quest).Owned == 1 && m.For("crafted", RecipeKind.Tradeskill).Required == 3 && m.For("crafted", RecipeKind.Tradeskill).Owned == 1 && !m.For("crafted", RecipeKind.Quest).HasAny); });
        test("Real nested SmIcon recipe templates do not truncate fields", () => { var fixture = Json.Read<List<PetItemRules.WikiFixture>>(Path.Combine(AppContext.BaseDirectory, "data", "crafting-evidence.json")).Single(x => x.Title == "Banded Mail"); var item = WikiClient.ParseItem(fixture.Title, fixture.Text, fixture.Revision); Check(item.CraftRecipes.Single().Inputs.Count == 3 && item.CraftRecipes.Single().Inputs.Sum(i => i.Count) == 5); });
        test("Collection quantities do not qualify material filters", () => { var c = new Catalog { Items = [new() { Key = "ingredient", Name = "Ingredient" }, new() { Key = "crafted", Name = "Crafted", CraftRecipes = [new() { Kind = RecipeKind.Tradeskill, Inputs = [new() { ItemKey = "ingredient" }] }] }] }; var m = new MaterialIndex(c, new() { Entries = [new() { Name = "Ingredient", Count = null }] }, new()); Check(!m.For("crafted", RecipeKind.Tradeskill).HasAny); });
        test("Self theory ratings are explicitly hypothetical without changing ordinary eligibility", () => { var item = new ItemDefinition { Key = "weapon", Name = "Weapon", Classes = ["CLR"], Slots = ["PRIMARY"], MetadataComplete = true, Stats = new() { ["STR"] = 5 } }; var c = new Catalog { Items = [item] }; var o = Owner(); o.EquipmentPositions = EquipmentPositions.FromEntries([]); foreach (var p in o.EquipmentPositions) p.Knowledge = EquipmentKnowledge.Empty; var ordinary = new LoadoutEvaluationSession(c, o, false, new() { ["STR"] = 1 }).Compare(item, 0, "PRIMARY:1"); var theory = new LoadoutEvaluationSession(c, o, false, new() { ["STR"] = 1 }, theorycraft: true).Compare(item, 0, "PRIMARY:1"); Check(ordinary.Eligibility != "Eligible" && theory.IsHypothetical && theory.Assumptions.Count > 0 && theory.Unbuffed.Delta == 5); });
    }
}
